// Scientific name -> profile id, for mapping a detection (which only has the
// scientific name) to a renderable species. Built from SPECIES_NA at import.
export const SCI_TO_ID = Object.fromEntries(
  Object.entries(SPECIES_NA).map(([id, p]) => [p.sci, id])
);
